import { spawn, spawnSync } from "node:child_process";
import { Command } from "commander";
import { errorFactories, FliskError, runCommand } from "../utils/errors.js";
import { JsonCommandError, runJsonCommand } from "../utils/json-command.js";
import { planNativeRun } from "../utils/native-runtime.js";
import { isNativeService } from "../utils/native-service.js";
import { runVariables } from "../utils/native-up.js";
import { findProjectRoot } from "../utils/paths.js";
import { discoverResourcesFromRoot } from "../utils/services.js";
import { readProjectName } from "../utils/shared-infra.js";
/**
 * `flisk run <service> -- <command> [args...]` (#2872): a one-off command (a seed script, a test-data factory, a REPL, a
 * migration status check) with the environment `<service>` has in the stack, so nobody copies `DATABASE_URL` or an API URL
 * by hand or points a tool at a shared environment.
 *
 * - A container service: `docker exec` in its running container, so the command sees exactly the env and networks the
 *   service has. It does not start the service: `flisk up <stack>` does.
 * - A local-process service (`command` in service.json): on the host, from the service folder, with the project `.env`, the
 *   shell, and the service's own `env` and PORT, as `flisk up` starts it.
 *
 * Interactive by default (stdin, stdout and stderr are passed through) and the command's exit code is flisk's. `--json` runs
 * it without input and reports the exit code and the output, for agents. Flisk itself never prints the environment.
 */
/** The most output `--json` keeps of each stream (the tail): enough for a status check, bounded for an agent. */
const JSON_OUTPUT_LIMIT = 64 * 1024;
/** Docker lowercases a Compose project name; Flisk names a stack's project `<project>-<stack>-autogenerated`. */
export function composeProjectFor(projectName, stack) {
    return `${projectName}-${stack}-autogenerated`.toLowerCase();
}
/** The id of the running container of a Compose service, or null. */
export function runningContainer(project, service, docker = (args) => spawnSync("docker", args, { encoding: "utf-8", timeout: 15_000 })) {
    const result = docker([
        "ps",
        "-q",
        "--filter",
        `label=com.docker.compose.project=${project}`,
        "--filter",
        `label=com.docker.compose.service=${service}`,
        "--filter",
        "status=running",
    ]);
    if (result.error || result.status !== 0) {
        throw new FliskError("Docker is not answering, so flisk run cannot reach the container.", [
            "Start Docker, then run the command again",
            "Check the machine with: flisk doctor",
        ]);
    }
    return result.stdout.trim().split(/\s+/)[0] || null;
}
export function resolveRunTarget(projectRoot, serviceName, command, options = { interactive: false }) {
    const resources = options.resources ?? discoverResourcesFromRoot(projectRoot);
    const resource = resources.find((candidate) => candidate.name === serviceName);
    if (!resource) {
        const names = resources.map((candidate) => candidate.name).sort();
        throw new FliskError(`No service named "${serviceName}" in this project.`, [
            names.length > 0 ? `Services: ${names.join(", ")}` : "This project has no services yet",
        ]);
    }
    const [file, ...args] = command;
    if (!file) {
        throw new FliskError("Give the command to run after --.", [
            `For example: flisk run ${serviceName} -- printenv DATABASE_URL`,
        ]);
    }
    if (isNativeService(resource)) {
        const vars = runVariables(projectRoot);
        const plan = planNativeRun([resource], vars).services[0];
        return {
            service: serviceName,
            runtime: "native",
            file,
            args,
            cwd: resource.path,
            env: { ...vars, ...(plan?.env ?? {}) },
        };
    }
    const stack = resource.stack ?? resource.config?.stack;
    const projectName = readProjectName(projectRoot);
    if (!stack || !projectName) {
        throw new FliskError(`Cannot tell which Compose project runs "${serviceName}".`, [
            "Check the service's stack and .flisk/project.json with: flisk doctor",
        ]);
    }
    const container = runningContainer(composeProjectFor(projectName, stack), serviceName);
    if (!container) {
        throw new FliskError(`"${serviceName}" is not running, so there is no container to run the command in.`, [`Start it with: flisk up ${stack}`, "Then run the command again"]);
    }
    const execFlags = options.interactive ? ["-i", ...(process.stdin.isTTY ? ["-t"] : [])] : [];
    return {
        service: serviceName,
        runtime: "container",
        file: "docker",
        args: ["exec", ...execFlags, container, file, ...args],
    };
}
function tail(text) {
    return text.length > JSON_OUTPUT_LIMIT ? text.slice(-JSON_OUTPUT_LIMIT) : text;
}
function runInteractive(target) {
    return new Promise((resolve, reject) => {
        const child = spawn(target.file, target.args, {
            cwd: target.cwd,
            env: target.env ?? process.env,
            stdio: "inherit",
        });
        child.once("error", (error) => reject(new FliskError(`Could not start "${target.file}": ${error.message}`, [
            "Check the command is installed where it runs (the container, or this machine for a local process)",
        ])));
        child.once("exit", (code, signal) => resolve(code ?? (signal ? 128 + 1 : 1)));
    });
}
export const runServiceCommand = new Command("run")
    .description("Run a one-off command with the environment a service has in the stack")
    .argument("<service>", "Name of the service whose environment the command gets")
    .argument("[command...]", "The command and its arguments, after --")
    .option("--json", "Run without input and print one JSON object with the exit code and the output", false)
    .addHelpText("after", "\nExamples:\n  flisk run orders-api -- printenv DATABASE_URL\n  flisk run orders-api -- bun run seed\n  flisk run orders-api -- sh")
    .action(async (service, command, options) => {
    if (options.json) {
        await runJsonCommand("RUN_FAILED", "flisk run", async () => {
            const projectRoot = findProjectRoot();
            if (!projectRoot)
                throw errorFactories.notInProject();
            let target;
            try {
                target = resolveRunTarget(projectRoot, service, command, { interactive: false });
            }
            catch (error) {
                if (!(error instanceof FliskError))
                    throw error;
                throw new JsonCommandError("RUN_FAILED", error.message, error.suggestions, error.exitCode);
            }
            const result = spawnSync(target.file, target.args, {
                cwd: target.cwd,
                env: target.env ?? process.env,
                encoding: "utf-8",
                stdio: ["ignore", "pipe", "pipe"],
                maxBuffer: 32 * 1024 * 1024,
                timeout: 10 * 60_000,
            });
            if (result.error) {
                throw new JsonCommandError("RUN_FAILED", `Could not start "${target.file}": ${result.error.message}`, [
                    "Check the command is installed where it runs (the container, or this machine for a local process)",
                ]);
            }
            const exitCode = result.status ?? 1;
            process.exitCode = exitCode;
            return {
                data: {
                    service: target.service,
                    runtime: target.runtime,
                    command,
                    exitCode,
                    stdout: tail(result.stdout ?? ""),
                    stderr: tail(result.stderr ?? ""),
                },
            };
        });
        return;
    }
    await runCommand(async () => {
        const projectRoot = findProjectRoot();
        if (!projectRoot)
            throw errorFactories.notInProject();
        const target = resolveRunTarget(projectRoot, service, command, { interactive: true });
        process.exitCode = await runInteractive(target);
    });
});
